// Runs in the browser or Node 18+ (POWER sends CORS headers)
const params = new URLSearchParams({
  parameters: "T2M,PRECTOTCORR",
  community: "AG",
  latitude: "42.03",
  longitude: "-93.63",
  start: "20250701",
  end: "20250707",
  format: "JSON",
});
const res = await fetch(`https://power.larc.nasa.gov/api/temporal/daily/point?${params}`);
const json = await res.json();
const temps = json.properties.parameter.T2M;
for (const [day, t] of Object.entries(temps)) {
  console.log(day, `${t} C`);
}

// No key, CORS enabled: works directly in the browser
const q = encodeURIComponent("Apollo 15 lunar roving vehicle");
const res = await fetch(`https://images-api.nasa.gov/search?q=${q}&media_type=image`);
const { collection } = await res.json();
console.log("hits:", collection.metadata.total_hits);
for (const item of collection.items.slice(0, 5)) {
  const meta = item.data[0];
  const thumb = item.links?.[0]?.href;
  console.log(meta.nasa_id, "|", meta.title, "|", thumb);
}

